function toTC(s){ return s.toLowerCase().replace(/\b\w/g, c=>c.toUpperCase()); }
function norm(n){
  if(!n) return "";
  const k = n.trim();
  return NAME_MAP[k.toLowerCase()] || toTC(k);
}
function normField(f){
  if(!f) return "";
  return f.split(/[\/,]/).map(p=>norm(p.trim())).filter(Boolean).join("/");
}
function err(label, e){
  console.error("❌ " + label + ":", e.message || e.details || JSON.stringify(e));
}
